# Extract TRG for P81-P86 from page10
rows_page10 = tables['supp.pdf']['page10']['rows']
print("Page10 rows for P81-P86:")
for i, row in enumerate(rows_page10):
    if len(row) < 8:
        continue
    cell = row[0]
    if isinstance(cell, dict):
        val = str(cell.get('value', ''))
    else:
        val = str(cell)
    if 'Patient-81' in val or 'Patient-82' in val or 'Patient-83' in val or 'Patient-84' in val or 'Patient-85' in val or 'Patient-86' in val:
        trg = row[7] if len(row) > 7 else None
        if isinstance(trg, dict):
            trg_val = str(trg.get('value', ''))
        else:
            trg_val = str(trg)
        print(f"  {val}: TRG={trg_val}")
